    console.log('✓ Step 10 passed\n');

    console.log('All tests passed! ✓');

  } catch (error) {
    results.status = 'failed';
    results.error = error.message;
    console.error(`\n❌ Test failed: ${error.message}`);
  } finally {
    if (browser) {
      await browser.close();
    }
  }

  return results;
}

